namespace Slic3r::GUI::JusPrin::Updates {

class UpdateCheck
{
public:
    enum class Status {
        NotChecked,
        Checking,
        UpToDate,
        Available, // a newer release was found, at the last check or an earlier one
        Failed,    // the last check could not read the release list
        Store,     // a Microsoft Store install: the Store updates it, JusPrin does not check
    };

    struct State
    {
        Status                 status{Status::NotChecked};
        std::string            version; // the running JusPrin
        std::optional<Release> available;
        std::time_t            last_success{0}; // 0: never
        bool                   auto_check{true};
    };

    State state() const;

    // Runs the daily schedule while `frame` exists, starting a few seconds
    // from now.
    void attach(MainFrame& frame);
    // Checks at once, whether or not the daily check is on. Does nothing
    // while a check is under way or for a Store install.
    void check_now();
    // "Skip this version" on the release the page showed: it is no longer
    // offered, and neither is anything older.
    void skip(const std::string& version);
    // JusPrin needs a newer version (the server no longer serves this one, or
    // a project was saved by a newer one): a skipped version is offered again.
    void unskip();

    // Calls `listener` on the UI thread whenever state() changes.
    int  subscribe(std::function<void()> listener);
    void unsubscribe(int token);

private:
    void tick(bool at_startup);
    void finish(std::time_t now, const std::optional<std::string>& body);
    void notify();

    std::unique_ptr<wxTimer>              m_timer;
    bool                                  m_checking{false};
    bool                                  m_started{false}; // the first tick of this run has passed
    std::map<int, std::function<void()>>  m_listeners;
    int                                   m_next_token{0};
};

// The one update check of this run.
UpdateCheck& update_check();

} // namespace Slic3r::GUI::JusPrin::Updates
#pragma once

// What JusPrin's update check remembers between runs, and when it runs
// next. Kept in AppConfig; GUI-free.

#include "ReleaseFeed.hpp"

#include <ctime>
#include <optional>
#include <string>

namespace Slic3r { class AppConfig; }

namespace Slic3r::GUI::JusPrin::Updates {

// "New JusPrin versions" in Preferences > Updates: "false" turns the daily
// check off. Check now still works.
inline constexpr char kAutoCheckKey[] = "jusprin_update_check";
// Where the release list is read from, for tests against a local server.
inline constexpr char kFeedUrlKey[] = "jusprin_update_feed_url";

struct UpdateRecord
{
    std::time_t            last_attempt{0}; // 0: never
    std::time_t            last_success{0};
    bool                   last_failed{false};
    std::optional<Release> available; // newer than the running version
};

bool auto_check_enabled(const AppConfig& config);

// A release remembered from an earlier run is dropped once the running
// version has caught up with it, and so is a skipped one.
UpdateRecord load_record(const AppConfig& config, const std::string& running);
void         save_success(AppConfig& config, std::time_t now, const std::optional<Release>& available);
void         save_failure(AppConfig& config, std::time_t now);
// "Skip this version": that version and older ones are no longer offered.
void         skip_version(AppConfig& config, const std::string& version);
// Offers a skipped version again.
void         unskip(AppConfig& config);

// Whether the daily check should run: a day after the last attempt and, at
// startup, also when the last attempt failed.
bool check_due(const UpdateRecord& record, std::time_t now, bool at_startup);

} // namespace Slic3r::GUI::JusPrin::Updates
#include "UpdateRecord.hpp"

#include "libslic3r/AppConfig.hpp"
#include "libslic3r/Semver.hpp"

namespace Slic3r::GUI::JusPrin::Updates {

namespace {

constexpr char        kLastAttemptKey[] = "jusprin_update_last_attempt";
constexpr char        kLastSuccessKey[] = "jusprin_update_last_success";
constexpr char        kLastFailedKey[]  = "jusprin_update_last_failed";
constexpr char        kVersionKey[]     = "jusprin_update_version";
constexpr char        kUrlKey[]         = "jusprin_update_url";
constexpr char        kPublishedKey[]   = "jusprin_update_published";
constexpr char        kNotesKey[]       = "jusprin_update_notes";
constexpr char        kSkippedKey[]     = "jusprin_update_skipped";
constexpr std::time_t kDay              = 24 * 60 * 60;

std::time_t read_time(const AppConfig& config, const char* key)
{
    const std::string value = config.get(key);
    return value.empty() ? 0 : static_cast<std::time_t>(std::stoll(value));
}

} // namespace

// Written with set_bool, as Preferences writes its switches; on until turned off.
bool auto_check_enabled(const AppConfig& config) { return config.get(kAutoCheckKey) != "false"; }

UpdateRecord load_record(const AppConfig& config, const std::string& running)
{
    UpdateRecord record;
    record.last_attempt = read_time(config, kLastAttemptKey);
    record.last_success = read_time(config, kLastSuccessKey);
    record.last_failed  = config.get(kLastFailedKey) == "1";
    const std::string version = config.get(kVersionKey);
    const auto        parsed  = Semver::parse(version);
    if (!parsed || !(Semver(running) < *parsed))
        return record;
    if (const auto skipped = Semver::parse(config.get(kSkippedKey)); skipped && !(*skipped < *parsed))
        return record;
    record.available = Release{version, config.get(kUrlKey), config.get(kPublishedKey), config.get(kNotesKey)};
    return record;
}

void save_success(AppConfig& config, std::time_t now, const std::optional<Release>& available)
{
    config.set(kLastAttemptKey, std::to_string(now));
    config.set(kLastSuccessKey, std::to_string(now));
    config.set(kLastFailedKey, "0");
    config.set(kVersionKey, available ? available->version : std::string());
    config.set(kUrlKey, available ? available->url : std::string());
    config.set(kPublishedKey, available ? available->published : std::string());
    config.set(kNotesKey, available ? available->notes : std::string());
}

void save_failure(AppConfig& config, std::time_t now)
{
    config.set(kLastAttemptKey, std::to_string(now));
    config.set(kLastFailedKey, "1");
}

void skip_version(AppConfig& config, const std::string& version) { config.set(kSkippedKey, version); }
void unskip(AppConfig& config) { config.set(kSkippedKey, std::string()); }

bool check_due(const UpdateRecord& record, std::time_t now, bool at_startup)
{
    if (at_startup && record.last_failed)
        return true;
    // A clock set back past the last attempt must not hold the check off.
    return now < record.last_attempt || now - record.last_attempt >= kDay;
}

} // namespace Slic3r::GUI::JusPrin::Updates
