// THROWAWAY PROTOTYPE: install-and-restart on macOS through Sparkle 2.
//
// Sparkle.framework is not linked: it is loaded from the bundle's Frameworks
// folder at run time, so a build without it behaves as before. The user
// driver below is Sparkle's hook for an app that draws its own update UI; it
// answers every question with "install" and shows a plain progress dialog.
// Every step appends a timed line to proto-log.txt beside the app bundle.

#include "SparklePrototype.hpp"

#include "libslic3r/AppConfig.hpp"
#include "slic3r/GUI/GUI_App.hpp"

#include <wx/progdlg.h>

#import <Cocoa/Cocoa.h>
#import <Sparkle/Sparkle.h>

#include <string>

namespace {

void timeline(NSString* line)
{
    NSString* dir  = [[[NSBundle mainBundle] bundlePath] stringByDeletingLastPathComponent];
    NSString* path = [dir stringByAppendingPathComponent:@"proto-log.txt"];
    NSDateFormatter* f = [NSDateFormatter new];
    f.dateFormat       = @"HH:mm:ss.SSS";
    NSString* text = [NSString stringWithFormat:@"%@ [app pid %d %@] %@\n", [f stringFromDate:[NSDate date]], getpid(),
                                                [[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleShortVersionString"], line];
    NSFileHandle* h = [NSFileHandle fileHandleForWritingAtPath:path];
    if (!h) {
        [text writeToFile:path atomically:NO encoding:NSUTF8StringEncoding error:nil];
        return;
    }
    [h seekToEndOfFile];
    [h writeData:[text dataUsingEncoding:NSUTF8StringEncoding]];
    [h closeFile];
}

wxProgressDialog* g_progress = nullptr;
uint64_t          g_expected = 0;
uint64_t          g_received = 0;

void close_progress()
{
    if (g_progress) {
        g_progress->Destroy();
        g_progress = nullptr;
    }
}

} // namespace

@interface JPProtoUserDriver : NSObject <SPUUserDriver>
@end

@implementation JPProtoUserDriver

- (void)showUpdatePermissionRequest:(SPUUpdatePermissionRequest*)request reply:(void (^)(SUUpdatePermissionResponse*))reply
{
    timeline(@"Sparkle asked for permission to check automatically: answered no");
    Class response = NSClassFromString(@"SUUpdatePermissionResponse");
    reply([[response alloc] initWithAutomaticUpdateChecks:NO sendSystemProfile:NO]);
}

- (void)showUserInitiatedUpdateCheckWithCancellation:(void (^)(void))cancellation { timeline(@"checking the update list"); }

- (void)showUpdateFoundWithAppcastItem:(SUAppcastItem*)item state:(SPUUserUpdateState*)state reply:(void (^)(SPUUserUpdateChoice))reply
{
    timeline([NSString stringWithFormat:@"found %@ (stage %ld): answered install", item.displayVersionString, (long) state.stage]);
    reply(SPUUserUpdateChoiceInstall);
}

- (void)showUpdateReleaseNotesWithDownloadData:(SPUDownloadData*)downloadData {}
- (void)showUpdateReleaseNotesFailedToDownloadWithError:(NSError*)error {}

- (void)showUpdateNotFoundWithError:(NSError*)error acknowledgement:(void (^)(void))acknowledgement
{
    timeline([NSString stringWithFormat:@"no update: %@", error.localizedDescription]);
    acknowledgement();
}

- (void)showUpdaterError:(NSError*)error acknowledgement:(void (^)(void))acknowledgement
{
    timeline([NSString stringWithFormat:@"updater error %@ %ld: %@ | %@", error.domain, (long) error.code, error.localizedDescription,
                                        error.userInfo[NSUnderlyingErrorKey]]);
    close_progress();
    wxMessageBox(wxString::FromUTF8([error.localizedDescription UTF8String]), "JusPrin update (prototype)");
    acknowledgement();
}

- (void)showDownloadInitiatedWithCancellation:(void (^)(void))cancellation
{
    timeline(@"download started");
    g_expected = g_received = 0;
    close_progress();
    g_progress = new wxProgressDialog("JusPrin update", "Downloading the new version…", 1000, nullptr, wxPD_AUTO_HIDE | wxPD_ELAPSED_TIME);
}

- (void)showDownloadDidReceiveExpectedContentLength:(uint64_t)expectedContentLength
{
    g_expected = expectedContentLength;
    timeline([NSString stringWithFormat:@"download size %llu bytes", expectedContentLength]);
}

- (void)showDownloadDidReceiveDataOfLength:(uint64_t)length
{
    g_received += length;
    if (g_progress && g_expected > 0)
        g_progress->Update(int(std::min<uint64_t>(999, 1000 * g_received / g_expected)));
}

- (void)showDownloadDidStartExtractingUpdate
{
    timeline([NSString stringWithFormat:@"downloaded %llu bytes; extracting", g_received]);
    if (g_progress)
        g_progress->Update(0, "Preparing the new version…");
}

- (void)showExtractionReceivedProgress:(double)progress
{
    if (g_progress)
        g_progress->Update(int(std::min(999.0, 1000 * progress)));
}

- (void)showReadyToInstallAndRelaunch:(void (^)(SPUUserUpdateChoice))reply
{
    timeline(@"ready to install and relaunch: answered install");
    close_progress();
    reply(SPUUserUpdateChoiceInstall);
}

- (void)showInstallingUpdateWithApplicationTerminated:(BOOL)applicationTerminated retryTerminatingApplication:(void (^)(void))retry
{
    timeline([NSString stringWithFormat:@"installing; app terminated: %d", applicationTerminated]);
}

- (void)showUpdateInstalledAndRelaunched:(BOOL)relaunched acknowledgement:(void (^)(void))acknowledgement
{
    timeline([NSString stringWithFormat:@"installed; relaunched: %d", relaunched]);
    acknowledgement();
}

- (void)dismissUpdateInstallation
{
    timeline(@"update UI dismissed");
    close_progress();
}

@end

@interface JPProtoUpdaterDelegate : NSObject <SPUUpdaterDelegate>
@property (copy) NSString* feed;
@end

@implementation JPProtoUpdaterDelegate
- (nullable NSString*)feedURLStringForUpdater:(SPUUpdater*)updater { return self.feed; }
- (void)updaterWillRelaunchApplication:(SPUUpdater*)updater { timeline(@"Sparkle will relaunch the app"); }
- (void)updater:(SPUUpdater*)updater didAbortWithError:(NSError*)error
{
    timeline([NSString stringWithFormat:@"aborted: %@ %ld %@", error.domain, (long) error.code, error.localizedDescription]);
}
@end

namespace Slic3r::GUI::JusPrin::Updates {

bool sparkle_prototype_start()
{
    static id updater;
    static JPProtoUserDriver*       driver;
    static JPProtoUpdaterDelegate*  delegate;

    const std::string feed = wxGetApp().app_config->get("jusprin_proto_appcast_url");
    NSString* framework = [[[NSBundle mainBundle] privateFrameworksPath] stringByAppendingPathComponent:@"Sparkle.framework"];
    NSBundle* sparkle   = [NSBundle bundleWithPath:framework];
    if (feed.empty() || !sparkle)
        return false;
    if (!updater) {
        NSError* error = nil;
        if (![sparkle loadAndReturnError:&error]) {
            timeline([NSString stringWithFormat:@"could not load Sparkle: %@", error]);
            return false;
        }
        driver        = [JPProtoUserDriver new];
        delegate      = [JPProtoUpdaterDelegate new];
        delegate.feed = [NSString stringWithUTF8String:feed.c_str()];
        updater       = [[NSClassFromString(@"SPUUpdater") alloc] initWithHostBundle:[NSBundle mainBundle]
                                                               applicationBundle:[NSBundle mainBundle]
                                                                      userDriver:driver
                                                                        delegate:delegate];
        if (![updater startUpdater:&error]) {
            timeline([NSString stringWithFormat:@"could not start Sparkle: %@", error]);
            updater = nil;
            return false;
        }
    }
    timeline(@"clicked: install and restart");
    [updater checkForUpdates];
    return true;
}

} // namespace Slic3r::GUI::JusPrin::Updates

#pragma once

// THROWAWAY PROTOTYPE: see SparklePrototype.mm.

namespace Slic3r::GUI::JusPrin::Updates {

// Starts Sparkle's check and install when Sparkle.framework is in the bundle
// and AppConfig has jusprin_proto_appcast_url; false otherwise.
bool sparkle_prototype_start();

} // namespace Slic3r::GUI::JusPrin::Updates
